// Exact piecewise cubic volume of continuous linear triangular terrain.
struct Span { const double* p=nullptr; size_t n=0; double operator[](size_t i)const{return p[i];} };
static Span view(napi_env e,napi_value o,const char* k){napi_typedarray_type t;size_t n,off;void* p;napi_value b;need(napi_get_typedarray_info(e,prop(e,o,k),&t,&n,&p,&b,&off)==napi_ok&&t==napi_float64_array,std::string("Expected Float64Array ")+k);return {(double*)p,n};}
struct Poly {
 const double *z,*v,*a,*b,*t;size_t n;
 double volume(double h)const{if(h<=z[0])return 0;size_t k=std::upper_bound(z,z+n,h)-z-1;double x=h-z[k];return std::max(0.,v[k]+x*(a[k]+x*(b[k]/2+x*t[k]/6)));}
 double area(double h)const{if(h<=z[0])return 0;size_t k=std::upper_bound(z,z+n,h)-z-1;double x=h-z[k];return std::clamp(a[k]+x*(b[k]+x*t[k]/2),0.,a[n-1]);}
 double level(double q)const{if(q<=0)return z[0];if(q>=v[n-1])return z[n-1]+(q-v[n-1])/a[n-1];size_t k=std::upper_bound(v,v+n,q)-v-1;
#ifdef POLY_CUBIC_FAST
 if(v[k]==0&&a[k]==0&&b[k]==0&&t[k]>0)return z[k]+std::cbrt(6*q/t[k]);
#endif
 double lo=0,hi=z[k+1]-z[k],x=hi*(q-v[k])/(v[k+1]-v[k]);for(int j=0;j<60;j++){double f=v[k]+x*(a[k]+x*(b[k]/2+x*t[k]/6))-q;if(std::abs(f)<=std::max(1e-30,q*2e-14))break;if(f>0)hi=x;else lo=x;double area=a[k]+x*(b[k]+x*t[k]/2),next=area>0?x-f/area:-1;next=next>lo&&next<hi?next:(lo+hi)/2;if(next==x)break;x=next;}return z[k]+x;}
};
struct Tri {long double lo,mid,hi,area;};
static std::array<long double,4> exact(const vector<Tri>& ts,long double h){std::array<long double,4> s{};for(auto q:ts){auto a=q.area;if(h<=q.lo)continue;if(h>=q.hi){s[0]+=a*(h-(q.lo+q.mid+q.hi)/3);s[1]+=a;}else if(h<q.mid){auto x=h-q.lo,d=(q.mid-q.lo)*(q.hi-q.lo);s[0]+=a*x*x*x/(3*d);s[1]+=a*x*x/d;s[2]+=2*a*x/d;s[3]+=2*a/d;}else{auto x=q.hi-h,d=(q.hi-q.lo)*(q.hi-q.mid);s[0]+=a*(h-(q.lo+q.mid+q.hi)/3)+a*x*x*x/(3*d);s[1]+=a*(1-x*x/d);s[2]+=2*a*x/d;s[3]-=2*a/d;}}return s;}
static napi_value buildCurve(napi_env env,napi_callback_info info){try{size_t argc=1;napi_value args[1];napi_get_cb_info(env,info,&argc,args,nullptr,nullptr);need(argc==1,"Expected mesh");auto zs=array(env,args[0],"z");int n=int(number(env,args[0],"n"));double area=number(env,args[0],"areaM2");need(n>=1&&n<=128&&zs.size()==size_t((n+1)*(n+1)+2*n*n)&&area>0,"Invalid mesh");for(double z:zs)need(std::isfinite(z),"Invalid mesh height");auto knots=zs;std::sort(knots.begin(),knots.end());knots.erase(std::unique(knots.begin(),knots.end()),knots.end());size_t len=knots.size();vector<size_t> rank;for(double z:zs)rank.push_back(std::lower_bound(knots.begin(),knots.end(),z)-knots.begin());vector<std::array<long double,3>> delta(len);vector<Tri> ts;long double ta=(long double)area/(6*n*n);
 auto triangle=[&](size_t x,size_t y,size_t c){std::array<size_t,3> r{rank[x],rank[y],rank[c]};std::sort(r.begin(),r.end());size_t l=r[0],m=r[1],h=r[2];long double lo=knots[l],mid=knots[m],hi=knots[h];ts.push_back({lo,mid,hi,ta});if(l==h){delta[l][0]+=ta;}else if(l==m){auto d=hi-lo;delta[l][1]+=2*ta/d;delta[l][2]-=2*ta/(d*d);delta[h][2]+=2*ta/(d*d);}else if(m==h){auto d=hi-lo;delta[l][2]+=2*ta/(d*d);delta[h][2]-=2*ta/(d*d);delta[h][1]-=2*ta/d;}else{auto lower=2*ta/((mid-lo)*(hi-lo)),upper=2*ta/((hi-lo)*(hi-mid));delta[l][2]+=lower;delta[m][2]-=lower+upper;delta[h][2]+=upper;}};
 size_t c=(n+1)*(n+1);for(int y=0;y<n;y++)for(int x=0;x<n;x++){size_t a=y*(n+1)+x,b=a+1,d=a+n+2,e=d-1;for(auto t:{std::array<size_t,3>{a,b,d},std::array<size_t,3>{a,d,e}}){triangle(t[0],t[1],c);triangle(t[1],t[2],c);triangle(t[2],t[0],c);c++;}}
 vector<double> v(len),a(len),b(len),t(len);std::array<long double,4> s{};double maxError=0;for(size_t k=0;k<len;k++){if(k){long double x=(long double)knots[k]-knots[k-1];s[0]+=x*(s[1]+x*(s[2]/2+x*s[3]/6));s[1]+=x*(s[2]+x*s[3]/2);s[2]+=x*s[3];}s[1]+=delta[k][0];s[2]+=delta[k][1];s[3]+=delta[k][2];if(k%32==0||k+1==len){long double h=k+1<len?((long double)knots[k]+knots[k+1])/2:knots[k],x=(long double)knots[k]-h;auto direct=exact(ts,h);direct[0]+=x*(direct[1]+x*(direct[2]/2+x*direct[3]/6));direct[1]+=x*(direct[2]+x*direct[3]/2);direct[2]+=x*direct[3];maxError=std::max(maxError,double(std::abs(s[0]-direct[0])));s=direct;}if(k==0)s={0,delta[0][0],delta[0][1],delta[0][2]};v[k]=double(s[0]);a[k]=double(s[1]);b[k]=double(s[2]);t[k]=double(s[3]);need(v[k]>=-1e-5&&a[k]>=-1e-5&&a[k]<=area*(1+1e-11),"Nonphysical polynomial curve");if(k)need(v[k]>=v[k-1],"Nonmonotone curve");}v[0]=0;auto full=exact(ts,knots.back());v.back()=full[0];a.back()=area;b.back()=t.back()=0;
 napi_value out;napi_create_object(env,&out);put(env,out,"z",knots);put(env,out,"v",v);put(env,out,"a",a);put(env,out,"b",b);put(env,out,"t",t);putnum(env,out,"maxReanchorVolumeCorrectionM3",maxError);return out;}catch(const std::exception& e){napi_throw_error(env,nullptr,e.what());return nullptr;}}
